int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<pair<int64, int64>> intervals(N);
    for (int i = 0; i < N; i++) {
        int64 l, r;
        cin >> l >> r;
        intervals[i] = {-l, r}; // store as [-L_i, R_i]
    }

    // Sort by left endpoint
    sort(intervals.begin(), intervals.end());

    int64 cost = 0;
    int64 cur_left = intervals[0].first;
    int64 cur_right = intervals[0].second;

    for (int i = 1; i < N; i++) {
        int64 l = intervals[i].first;
        int64 r = intervals[i].second;

        if (l < cur_right) {
            // Overlap detected
            int64 overlap = cur_right - l;
            // Move this interval right by overlap
            cost += overlap;
            l += overlap;
            r += overlap;
        }

        if (r > cur_right) {
            cur_right = r;
        }
        cur_left = l;
    }

    cout << cost << "\n";
