using int64 = long long;
const long long INF = (1LL << 62);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<long long> L(N), R(N), len(N);
    long long sumLen = 0;
    for (int i = 0; i < N; ++i) {
        cin >> L[i] >> R[i];
        len[i] = L[i] + R[i];           // interval is [-L_i, R_i], length = L_i + R_i
        sumLen += len[i];
    }

    // DP over subset:
    // dp[S] = minimum cost to place intervals in S consecutively on the left side,
    // ending exactly at position 0, i.e. occupying [-sumLen(S), 0] without overlap.
    //
    // If interval i is the last one in this arrangement, it occupies [-len[i], 0]
    // after shifting, whose center is at (R_i - L_i)/2 shifted by x.
    // Original interval is [-L_i, R_i], so to make its right end 0, shift by -R_i.
    // Thus when i is placed as the last block ending at 0, cost is R_i.
    //
    // More generally, if total length of S is W, and i is the last interval,
    // then interval i occupies [-(len[i]), 0] translated left by (W - len[i]),
    // so its right end is at -(W - len[i]).
    // Original right end is R_i, hence shift amount is R_i + (W - len[i]) = W - L_i.
    //
    // Therefore:
    // dp[S] = min over i in S of dp[S\{i}] + abs(sumLen(S) - L_i)
    //
    // Similarly, arranging on the right side starting at 0 gives symmetric cost
    // abs(sumLen(S) - R_i), but since original intervals all contain 0, optimal final
    // arrangement is some intervals on the left and the rest on the right.
    //
    // Let leftCost[S] = min cost for S packed on the left ending at 0.
    // Let rightCost[S] = min cost for S packed on the right starting at 0.
    //
    // Answer = min over S: leftCost[S] + rightCost[all \ S]

    int M = 1 << N;
    vector<long long> subsetLen(M, 0);
    for (int s = 1; s < M; ++s) {
        int b = __builtin_ctz(s);
        subsetLen[s] = subsetLen[s ^ (1 << b)] + len[b];
    }

    vector<long long> leftCost(M, INF), rightCost(M, INF);
    leftCost[0] = rightCost[0] = 0;

    for (int s = 1; s < M; ++s) {
        long long W = subsetLen[s];
        for (int i = 0; i < N; ++i) {
            if (s & (1 << i)) {
                int t = s ^ (1 << i);
                leftCost[s] = min(leftCost[s], leftCost[t] + llabs(W - L[i]));
                rightCost[s] = min(rightCost[s], rightCost[t] + llabs(W - R[i]));
            }
        }
    }

    long long ans = INF;
    int all = M - 1;
    for (int s = 0; s < M; ++s) {
        ans = min(ans, leftCost[s] + rightCost[all ^ s]);
    }

    cout << ans << '\n';
    return 0;
}

