#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long left;
    long long right;
} Interval;

int cmp(const void *a, const void *b) {
    long long la = ((Interval*)a)->left;
    long long lb = ((Interval*)b)->left;
    if (la < lb) return -1;
    if (la > lb) return 1;
    return 0;
}

int main() {
    int N;
    scanf("%d", &N);
    Interval *intervals = malloc(N * sizeof(Interval));
    for (int i = 0; i < N; i++) {
        int L, R;
        scanf("%d %d", &L, &R);
        intervals[i].left = -L;
        intervals[i].right = R;
    }

    qsort(intervals, N, sizeof(Interval), cmp);

    long long cost = 0;
    long long current_pos = intervals[0].left; 
    // We try to place intervals starting from the leftmost possible position

    for (int i = 0; i < N; i++) {
        long long original_left = intervals[i].left;
        long long len = intervals[i].right - intervals[i].left;

        // The earliest we can place this interval without overlap is current_pos
        long long new_left = current_pos;
        if (new_left < original_left) {
            // Moving right
            cost += (original_left - new_left);
        } else if (new_left > original_left) {
            // Moving left
            cost += (new_left - original_left);
        }
        // Update current_pos for next interval
        current_pos = new_left + len;
    }

    printf("%lld\n", cost);
    free(intervals);
    return 0;
}

