public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        int[] L = new int[N];
        int[] R = new int[N];
        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            L[i] = Integer.parseInt(st.nextToken());
            R[i] = Integer.parseInt(st.nextToken());
        }

        // Each interval i is represented as its center c_i = (R_i - L_i)/2
        // and half-length h_i = (L_i + R_i)/2.
        double[] center = new double[N];
        double[] half = new double[N];
        for (int i = 0; i < N; i++) {
            center[i] = (R[i] - L[i]) / 2.0;
            half[i] = (L[i] + R[i]) / 2.0;
        }

        // Pair centers with half-lengths and sort by center
        Integer[] idx = new Integer[N];
        for (int i = 0; i < N; i++) idx[i] = i;
        Arrays.sort(idx, Comparator.comparingDouble(i -> center[i]));

        double[] sortedCenter = new double[N];
        double[] sortedHalf = new double[N];
        for (int i = 0; i < N; i++) {
            sortedCenter[i] = center[idx[i]];
            sortedHalf[i] = half[idx[i]];
        }

        // prefix sums of half-lengths
        double[] prefHalf = new double[N+1];
        for (int i = 0; i < N; i++) {
            prefHalf[i+1] = prefHalf[i] + sortedHalf[i];
        }

        // dp[i] = min cost to make first i intervals non-overlapping
        double[] dp = new double[N+1];
        Arrays.fill(dp, Double.MAX_VALUE);
        dp[0] = 0;

        // For each i, we try to put intervals j..i-1 in one block without internal gaps
        for (int i = 1; i <= N; i++) {
            for (int j = 0; j < i; j++) {
                double sumHalf = prefHalf[i] - prefHalf[j];
                double avgCenter = 0;
                for (int k = j; k < i; k++) {
                    avgCenter += sortedCenter[k];
                }
                avgCenter /= (i - j);

                // In the optimal arrangement, the block will be placed so that
                // total movement cost is minimized: move each interval's center to
                // positions avgCenter + (k - j - (i-j-1)/2) * 2? Actually we need
                // to place them in order with exactly touching at endpoints.
                // For sorted intervals by center, the optimal placement is to keep
                // them in the same order with no gaps. The total movement cost
                // is sum |c_k - (x + 2 * (k - j) * h_avg? Let's derive properly.

                // Let the block start at position s. Then interval k (j-th in block)
                // occupies [s + 2*sum_{t=j}^{k-1} h_t, s + 2*sum_{t=j}^{k} h_t].
                // Its center is s + sum_{t=j}^{k-1} 2h_t + h_k.
                // We want to minimize sum |c_k - (s + offset_k)| over s.
                // This is a classic 1D median problem: s = median of (c_k - offset_k).

                double[] vals = new double[i-j];
                double offset = 0;
                for (int k = j; k < i; k++) {
                    vals[k-j] = sortedCenter[k] - offset;
                    offset += 2 * sortedHalf[k];
                }
                Arrays.sort(vals);
                double s = vals[(i-j)/2];

                double cost = 0;
                offset = 0;
                for (int k = j; k < i; k++) {
                    double targetCenter = s + offset;
                    cost += Math.abs(sortedCenter[k] - targetCenter);
                    offset += 2 * sortedHalf[k];
                }

                if (dp[j] + cost < dp[i]) {
                    dp[i] = dp[j] + cost;
                }
            }
        }

        System.out.printf("%.10f%n", dp[N]);
    }
}

