public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();

        long[] L = new long[N];
        long[] R = new long[N];
        long[] A = new long[N];
        long[] B = new long[N];

        for (int i = 0; i < N; i++) {
            L[i] = fs.nextLong();
            R[i] = fs.nextLong();
            A[i] = -L[i];
            B[i] = R[i];
        }

        // Sort by original center/order on line: by left endpoint A[i], tie by right endpoint B[i]
        Integer[] ord = new Integer[N];
        for (int i = 0; i < N; i++) ord[i] = i;
        Arrays.sort(ord, (i, j) -> {
            if (A[i] != A[j]) return Long.compare(A[i], A[j]);
            return Long.compare(B[i], B[j]);
        });

        long[] a = new long[N];
        long[] b = new long[N];
        for (int i = 0; i < N; i++) {
            a[i] = A[ord[i]];
            b[i] = B[ord[i]];
        }

        // Prefix cost to place intervals 0..i packed to the left, preserving order,
        // with right endpoint of interval i fixed at its original b[i].
        long[] pref = new long[N];
        long curLeft = b[0] - (b[0] - a[0]);
        pref[0] = 0;
        long leftMost = a[0];
        long right = b[0];
        pref[0] = 0;

        // Build packed positions from right to left in prefix
        long[] prefCost = new long[N];
        prefCost[0] = 0;
        long packedRight = b[0];
        for (int i = 1; i < N; i++) {
            // In packed arrangement ending at original b[i], interval i stays ending at b[i],
            // previous intervals are placed consecutively to its left.
            // Compute incrementally from i-1 packed ending at ? easier by recurrence on starts.
            // We'll use formula via total lengths.
        }

        // Simpler approach:
        // Let len[i] = b[i]-a[i]. For a block [0..i], packed with interval i ending at b[i]:
        // interval k occupies [ b[i] - sum_{t=k}^i len[t], b[i] - sum_{t=k+1}^i len[t] ]
        // cost = sum |newLeft_k - a[k]| = sum |newRight_k - b[k]|, same shift.
        // Since order sorted and optimal side split exists, we compute exact prefix/suffix costs
        // by transformed coordinates.

        long[] len = new long[N];
        for (int i = 0; i < N; i++) len[i] = b[i] - a[i];

        long[] sumLen = new long[N + 1];
        for (int i = 0; i < N; i++) sumLen[i + 1] = sumLen[i] + len[i];

        // For prefix [0..i], packed to the left ending at b[i]:
        // shift of interval k = (b[i] - (sumLen[i+1]-sumLen[k+1])) - b[k]
        // = (b[i] - sumLen[i+1]) - (b[k] - sumLen[k+1])
        // Since sorted intervals overlap around 0, these shifts are nonnegative in this packing setting.
        // So cost is sum over k of that expression.
        long[] x = new long[N];
        for (int k = 0; k < N; k++) x[k] = b[k] - sumLen[k + 1];

        long[] prefX = new long[N + 1];
        for (int i = 0; i < N; i++) prefX[i + 1] = prefX[i] + x[i];

        long[] leftCost = new long[N];
        for (int i = 0; i < N; i++) {
            long base = b[i] - sumLen[i + 1];
            leftCost[i] = (i + 1L) * base - prefX[i + 1];
        }

        // For suffix [i..N-1], packed to the right starting at a[i]:
        // shift of interval k = a[k] - (a[i] + (sumLen[k]-sumLen[i]))
        // = (a[k] - sumLen[k]) - (a[i] - sumLen[i])
        long[] y = new long[N];
        for (int k = 0; k < N; k++) y[k] = a[k] - sumLen[k];

        long[] suffY = new long[N + 1];
        for (int i = N - 1; i >= 0; i--) suffY[i] = suffY[i + 1] + y[i];

        long[] rightCost = new long[N];
        for (int i = 0; i < N; i++) {
            long base = a[i] - sumLen[i];
            rightCost[i] = suffY[i] - (N - i) * base;
        }

        long ans = Long.MAX_VALUE;

        // Split between i and i+1:
        // [0..i] packed left, [i+1..N-1] packed right.
        // Need gap/touch condition automatically holds iff packed prefix right end <= packed suffix left start.
        // Prefix right end is b[i], suffix left start is a[i+1].
        // If b[i] <= a[i+1], already separated.
        // Otherwise additional global separation needed by moving left block left and/or right block right
        // by total amount overlap = b[i]-a[i+1]. Cheapest is distribute arbitrarily, total same.
        // Cost adds overlap.
        for (int i = -1; i < N; i++) {
            long cost = 0;
            if (i >= 0) cost += leftCost[i];
            if (i + 1 < N) cost += rightCost[i + 1];

            long overlap = 0;
            if (i >= 0 && i + 1 < N) {
                overlap = Math.max(0L, b[i] - a[i + 1]);
            }
            cost += overlap;
            ans = Math.min(ans, cost);
        }

        System.out.println(ans);
    }
}

